diff --git a/api.mjs b/api.mjs
index 0e9ddde..78d8821 100644
--- a/api.mjs
+++ b/api.mjs
@@ -1,3 +1,7 @@
 export function splitName(full) {
-  return full.split(' ');
+  const parts = full.split(' ');
+  if (parts.length === 1) return [parts[0], ''];
+  const last = parts.pop();
+  const first = parts.join(' ');
+  return [last, first];
 }

